public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a visited array to keep track of the n-tersections that have been visited
    boolean[] visited = new boolean[n];

    // Initialize the visited array and the queue with the starting n-tersection
    visited[start[0]] = true;
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection and its coordinates
        int[] current = queue.remove();
        int x = current[0];
        int y = current[1];

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        // Loop through the paths between adjacent n-tersections
        for (int[] path : paths) {
            // If the current n-tersection is a path starting n-tersection, get the path end n-tersection
            if (x == path[0] && y == path[1]) {
                int[] end = new int[]{path[2], path[3]};

                // If the end n-tersection has not been visited, mark it as visited and add it to the queue
                if (!visited[end[0]]) {
                    visited[end[0]] = true;
                    queue.add(end);
                }
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    if (!visited[end[0]]) {
        return "cannot be travelled";
    }

    // Return "cannot be travelled" otherwise
    return "cannot be travelled";
}

