public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    int[][] cache = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int sq = (int) (Math.sqrt(A[i] + A[j]));
            if (sq * sq == A[i] + A[j]) {
                for (int k = 0; k < n; k++) {
                    cache[k][j] = dp[k][i] * dp[k][j];
                }
            }
            for (int k = 0; k < n; k++) {
                dp[k][j] = cache[k][j] % (1000000007);
            }
        }
    }
    int res = 0;
    for (int i = 0; i < n; i++) {
        res += dp[n - 1][i];
    }
    return res % 1000000007;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();
    stack.push(-1);
    for (int i = 0; i < heights.length; i++) {
        while (stack.peek() != -1 && heights[i] < heights[stack.peek()]) {
            int top = stack.pop();
            int area = heights[top] * (i - stack.peek() - 1);
            maxArea = Math.max(maxArea, area);
        }
        stack.push(i);
    }
    while (stack.peek() != -1) {
        int top = stack.pop();
        int area = heights[top] * (heights.length - stack.peek() - 1);
        maxArea = Math.max(maxArea, area);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int[] result = new int[mat.length * mat[0].length];
    int row = 0;
    int col = 0;
    int idx = 0;
    boolean up = true;
    while (row < mat.length && col < mat[0].length) {
        result[idx] = mat[row][col];
        if (up) {
            if (col == mat[0].length - 1) {
                row++;
                col--;
                up = false;
            } else if (row == mat.length - 1) {
                col++;
                up = true;
            } else {
                row++;
                col++;
            }
        } else {
            if (row == mat.length - 1) {
                row--;
                col++;
                up = true;
            } else if (col == 0) {
                row++;
                col++;
                up = false;
            } else {
                row--;
                col--;
            }
        }
        idx++;
    }
    return result;
}

